CREATE POLICY trusted_server ON easygas_private.users TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.sessions TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.auth_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.auth_attempts TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.products TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.inventory ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.inventory TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.stock_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.stock_movements TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.setting_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.setting_definitions TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.settings TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.change_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.change_requests TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.approval_decisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.approval_decisions TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.setting_versions ENABLE ROW LEVEL SECURITY;
