CREATE POLICY trusted_server ON easygas_private.notifications TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.orders TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.order_items TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.order_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.order_events TO easygas_server USING (true) WITH CHECK (true);
