ALTER TABLE easygas_private.wallet_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY trusted_server ON easygas_private.wallet_entries TO easygas_server USING (true) WITH CHECK (true);
ALTER TABLE easygas_private.reward_entries ENABLE ROW LEVEL SECURITY;
