REVOKE UPDATE ON easygas_private.audit_events,easygas_private.approval_decisions,easygas_private.setting_versions,easygas_private.stock_movements,easygas_private.wallet_entries,easygas_private.verified_payments FROM easygas_server;
-- Limit mutable columns to operations implemented by this release.
REVOKE INSERT,UPDATE ON easygas_private.setting_definitions,easygas_private.products FROM easygas_server;
REVOKE UPDATE ON easygas_private.order_items,easygas_private.reward_entries FROM easygas_server;
REVOKE UPDATE ON easygas_private.orders FROM easygas_server;
GRANT UPDATE(status,payment_status,driver_id) ON easygas_private.orders TO easygas_server;
