FOREACH t IN ARRAY ARRAY['recurring_authorisations','schedule_occurrences','campaigns','campaign_recipients'] LOOP
EXECUTE format('ALTER TABLE easygas_private.%I ENABLE ROW LEVEL SECURITY',t);
