INSERT INTO schema_migrations(version) VALUES ('037');
-- Existing databases may have recorded 023 before default-address support was added.
-- Preserve addresses and existing choices; never infer a customer's preferred address.
ALTER TABLE account_addresses ADD COLUMN IF NOT EXISTS is_default boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX IF NOT EXISTS address_default_once ON account_addresses(customer_id) WHERE is_default=true AND archived=false;

INSERT INTO schema_migrations(version) VALUES ('038');
-- Restore only the existing server capability for the additive compatibility column.
GRANT UPDATE(is_default) ON easygas_private.account_addresses TO easygas_server;

INSERT INTO schema_migrations(version) VALUES ('039');
-- Additive local rollout. Historical events keep version 0; no invented timestamps/actors.
ALTER TABLE orders ADD COLUMN tracking_version integer NOT NULL DEFAULT 0;
ALTER TABLE order_events ADD COLUMN version integer;
ALTER TABLE order_events ADD COLUMN previous_status text;
ALTER TABLE order_events ADD COLUMN correlation_id text;
CREATE INDEX order_events_order_version ON order_events(order_id,version);
CREATE TABLE delivery_attempts (
 id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), driver_id text NOT NULL REFERENCES users(id),
 assignment_version integer NOT NULL, state text NOT NULL CHECK(state IN ('assigned','picked_up','arrived','failed','delivered','returned')),
 picked_up_at timestamptz, arrived_at timestamptz, completed_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,assignment_version)
);
CREATE UNIQUE INDEX delivery_attempt_active ON delivery_attempts(order_id) WHERE state IN ('assigned','picked_up','arrived');
CREATE INDEX delivery_attempt_driver ON delivery_attempts(driver_id,state);
CREATE TABLE delivery_evidence (
 id text PRIMARY KEY, attempt_id text NOT NULL REFERENCES delivery_attempts(id), actor_id text NOT NULL REFERENCES users(id),
 kind text NOT NULL CHECK(kind IN ('pickup','arrived','failed','handover','return','rescheduled')),
 detail jsonb NOT NULL, operation_key text, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX delivery_evidence_attempt ON delivery_evidence(attempt_id,created_at);
CREATE TRIGGER delivery_evidence_immutable BEFORE UPDATE OR DELETE ON delivery_evidence FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TABLE order_event_outbox (
 event_id text PRIMARY KEY REFERENCES order_events(id), order_id text NOT NULL REFERENCES orders(id),
 version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), notified_at timestamptz
);
CREATE INDEX order_outbox_pending ON order_event_outbox(created_at) WHERE notified_at IS NULL;
CREATE FUNCTION record_order_tracking_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 SELECT status INTO NEW.previous_status FROM order_events WHERE order_id=NEW.order_id ORDER BY version DESC NULLS LAST,created_at DESC LIMIT 1;
 UPDATE orders SET tracking_version=tracking_version+1 WHERE id=NEW.order_id RETURNING tracking_version INTO NEW.version;
 NEW.correlation_id := COALESCE(NEW.correlation_id,NEW.id);
 RETURN NEW;
END $$;
CREATE TRIGGER order_event_version BEFORE INSERT ON order_events FOR EACH ROW EXECUTE FUNCTION record_order_tracking_event();
CREATE FUNCTION publish_order_tracking_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO order_event_outbox(event_id,order_id,version) VALUES(NEW.id,NEW.order_id,NEW.version);
 RETURN NEW;
END $$;
CREATE TRIGGER order_event_outbox AFTER INSERT ON order_events FOR EACH ROW EXECUTE FUNCTION publish_order_tracking_event();
CREATE TRIGGER order_events_immutable BEFORE UPDATE OR DELETE ON order_events FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['delivery_attempts','delivery_evidence','order_event_outbox'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO easygas_server',t);
 EXECUTE format('CREATE POLICY trusted_server ON %I TO easygas_server USING(true) WITH CHECK(true)',t);
 END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT UPDATE(tracking_version,delivery_date,delivery_window,delivery_code_hash,delivery_code_expires_at) ON orders TO easygas_server;
 END IF;
END $$;

INSERT INTO schema_migrations(version) VALUES ('040');
-- Link immutable event/proof records to the actual actor-scoped operation identity.
CREATE OR REPLACE FUNCTION record_order_tracking_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 SELECT status INTO NEW.previous_status FROM order_events WHERE order_id=NEW.order_id ORDER BY version DESC NULLS LAST,created_at DESC LIMIT 1;
 UPDATE orders SET tracking_version=tracking_version+1 WHERE id=NEW.order_id RETURNING tracking_version INTO NEW.version;
 NEW.correlation_id := COALESCE(NEW.correlation_id,NULLIF(current_setting('easygas.operation_key',true),''),NEW.id);
 RETURN NEW;
END $$;
ALTER TABLE delivery_evidence ALTER COLUMN operation_key SET DEFAULT NULLIF(current_setting('easygas.operation_key',true),'');
CREATE UNIQUE INDEX order_events_version_once ON order_events(order_id,version) WHERE version IS NOT NULL;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 REVOKE UPDATE ON delivery_evidence FROM easygas_server;
 REVOKE UPDATE ON order_event_outbox FROM easygas_server;
 GRANT UPDATE(notified_at) ON order_event_outbox TO easygas_server;
END IF; END $$;

INSERT INTO schema_migrations(version) VALUES ('041');
ALTER TABLE support_requests ADD COLUMN order_id text REFERENCES orders(id);
CREATE INDEX support_requests_order ON support_requests(order_id) WHERE order_id IS NOT NULL;

INSERT INTO schema_migrations(version) VALUES ('042');
-- Additive extension: existing users and reward_entries remain authoritative.
CREATE TABLE reward_entry_details (
 entry_id text PRIMARY KEY REFERENCES reward_entries(id),
 branch_id text NOT NULL REFERENCES branches(id),
 order_id text REFERENCES orders(id),
 policy_version_id text REFERENCES setting_versions(id),
 kind text NOT NULL CHECK(kind IN ('earned','redeemed','restored','reversed','referral','adjustment')),
 original_entry_id text REFERENCES reward_entries(id),
 detail jsonb NOT NULL DEFAULT '{}'
);
CREATE TRIGGER reward_details_immutable BEFORE UPDATE OR DELETE ON reward_entry_details FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE INDEX reward_details_order ON reward_entry_details(order_id);
CREATE TABLE reward_jobs (
 order_id text PRIMARY KEY REFERENCES orders(id),
 policy_version_id text NOT NULL REFERENCES setting_versions(id),
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','review')),
 attempts integer NOT NULL DEFAULT 0,
 last_error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz
);
CREATE INDEX reward_jobs_pending ON reward_jobs(created_at) WHERE status='pending';
INSERT INTO setting_definitions(key,label,category,description,owner_role,risk,value_type,propose_roles,approve_roles,view_roles,required_roles,additional_verification) VALUES
('loyalty.policy','EasyRewards policy','Loyalty','Versioned point economics. Example rates are not approved. Requires independent owner and finance approvals; technical flags remain separate.','owner',4,'rewards_policy','["owner","finance"]','["owner","finance"]','["owner","finance","manager"]','["owner","finance"]',true);
INSERT INTO settings(key,scope,value) SELECT 'loyalty.policy',id,'{"earningEnabled":false,"redemptionEnabled":false,"spendPerPointKobo":10000,"discountPerPointKobo":100,"minimumPoints":500,"maximumDiscountBps":2000,"eligibleCategories":["Gas refills"],"referralPoints":0,"referralEnabled":false}'::jsonb FROM branches;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN
  REVOKE ALL ON reward_entry_details,reward_jobs FROM anon;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN
  REVOKE ALL ON reward_entry_details,reward_jobs FROM authenticated;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
  GRANT SELECT,INSERT ON reward_entry_details TO easygas_server;
  GRANT SELECT,INSERT,UPDATE ON reward_jobs TO easygas_server;
 END IF;
END $$;
ALTER TABLE reward_entry_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE reward_jobs ENABLE ROW LEVEL SECURITY;
-- Discounts extend the existing order total; zero-discount legacy orders keep their invariant.
ALTER TABLE orders ADD COLUMN reward_discount_kobo bigint NOT NULL DEFAULT 0 CHECK(reward_discount_kobo>=0 AND reward_discount_kobo<=subtotal_kobo);
ALTER TABLE orders DROP CONSTRAINT orders_check;
ALTER TABLE orders ADD CONSTRAINT orders_total_with_rewards CHECK(total_kobo=subtotal_kobo+delivery_kobo-reward_discount_kobo);
CREATE TABLE reward_order_discounts (
 order_id text PRIMARY KEY REFERENCES orders(id),
 entry_id text NOT NULL UNIQUE REFERENCES reward_entries(id),
 policy_version_id text NOT NULL REFERENCES setting_versions(id),
 points integer NOT NULL CHECK(points>0),
 discount_kobo bigint NOT NULL CHECK(discount_kobo>0),
 eligible_kobo bigint NOT NULL CHECK(eligible_kobo>=discount_kobo),
 snapshot jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER reward_discounts_immutable BEFORE UPDATE OR DELETE ON reward_order_discounts FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
ALTER TABLE reward_jobs ADD COLUMN snapshot jsonb NOT NULL DEFAULT '{}';
ALTER TABLE reward_order_discounts ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT ON reward_order_discounts TO easygas_server;
END IF; END $$;
CREATE FUNCTION preserve_reward_job_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.order_id,NEW.policy_version_id,NEW.snapshot,NEW.created_at) IS DISTINCT FROM (OLD.order_id,OLD.policy_version_id,OLD.snapshot,OLD.created_at) THEN
  RAISE EXCEPTION 'Reward source snapshot is immutable';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER reward_job_source_immutable BEFORE UPDATE ON reward_jobs FOR EACH ROW EXECUTE FUNCTION preserve_reward_job_source();
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 REVOKE UPDATE ON reward_jobs FROM easygas_server;
 GRANT UPDATE(status,attempts,last_error,completed_at) ON reward_jobs TO easygas_server;
END IF; END $$;
INSERT INTO setting_definitions(key,label,category,description,owner_role,risk,value_type,propose_roles,approve_roles,view_roles,required_roles,additional_verification) VALUES
('loyalty.adjustment','Audited points adjustment','Loyalty','One immutable customer adjustment per approved request. Reason and evidence required. No wallet transfer.','owner',4,'rewards_adjustment','["owner","finance"]','["owner","finance"]','["owner","finance"]','["owner","finance"]',true);
INSERT INTO settings(key,scope,value) SELECT 'loyalty.adjustment',id,'{"customerId":"","points":0,"reason":"","evidence":""}'::jsonb FROM branches;
CREATE TABLE reward_referral_codes (
 customer_id text PRIMARY KEY REFERENCES users(id),
 code text NOT NULL UNIQUE CHECK(length(code)=32),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE reward_referrals (
 attribution_id text NOT NULL UNIQUE,
 customer_id text PRIMARY KEY REFERENCES users(id),
 referrer_id text NOT NULL REFERENCES users(id),
 code text NOT NULL REFERENCES reward_referral_codes(code),
 source_order_id text UNIQUE REFERENCES orders(id),
 awarded_entry_id text UNIQUE REFERENCES reward_entries(id),
 created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(customer_id<>referrer_id)
);
CREATE TRIGGER reward_codes_immutable BEFORE UPDATE OR DELETE ON reward_referral_codes FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE FUNCTION preserve_reward_referral() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.attribution_id,NEW.customer_id,NEW.referrer_id,NEW.code,NEW.created_at) IS DISTINCT FROM (OLD.attribution_id,OLD.customer_id,OLD.referrer_id,OLD.code,OLD.created_at) OR OLD.awarded_entry_id IS NOT NULL THEN
  RAISE EXCEPTION 'Referral attribution and committed award are immutable';
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER reward_referral_immutable BEFORE UPDATE ON reward_referrals FOR EACH ROW EXECUTE FUNCTION preserve_reward_referral();
ALTER TABLE reward_referral_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE reward_referrals ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT ON reward_referral_codes,reward_referrals TO easygas_server;
 GRANT UPDATE(source_order_id,awarded_entry_id) ON reward_referrals TO easygas_server;
END IF; END $$;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON reward_order_discounts,reward_referral_codes,reward_referrals FROM anon; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON reward_order_discounts,reward_referral_codes,reward_referrals FROM authenticated; END IF;
END $$;
CREATE FUNCTION preserve_order_reward_discount() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.reward_discount_kobo>0 AND NEW.reward_discount_kobo<>OLD.reward_discount_kobo THEN
  RAISE EXCEPTION 'Posted order reward discount is immutable';
 END IF;
 IF NEW.reward_discount_kobo>0 AND NOT EXISTS(SELECT 1 FROM reward_order_discounts d WHERE d.order_id=NEW.id AND d.discount_kobo=NEW.reward_discount_kobo) THEN
  RAISE EXCEPTION 'Order discount must match immutable point evidence';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER order_reward_discount_evidence BEFORE UPDATE OF reward_discount_kobo,total_kobo ON orders FOR EACH ROW EXECUTE FUNCTION preserve_order_reward_discount();

INSERT INTO schema_migrations(version) VALUES ('043'),('043c');
-- Existing orders and credit_requests remain the financial authorities.
ALTER TABLE credit_requests ADD COLUMN refund_lines jsonb;
ALTER TABLE credit_requests ADD COLUMN refund_fingerprint text;
ALTER TABLE credit_requests ADD COLUMN refund_operation_key text;
CREATE UNIQUE INDEX refund_operation_customer ON credit_requests(customer_id,refund_operation_key) WHERE refund_operation_key IS NOT NULL;
DROP INDEX full_refund_once_idx;
CREATE UNIQUE INDEX pending_refund_once ON credit_requests(order_id) WHERE kind='refund' AND status='pending';
CREATE TABLE reward_refund_allocations (
 credit_id text PRIMARY KEY REFERENCES credit_requests(id),order_id text NOT NULL REFERENCES orders(id),
 gross_kobo bigint NOT NULL CHECK(gross_kobo>=0),discount_kobo bigint NOT NULL CHECK(discount_kobo>=0),
 returned_points integer NOT NULL CHECK(returned_points>=0),reversed_points integer NOT NULL CHECK(reversed_points>=0),
 detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER reward_refund_allocations_immutable BEFORE UPDATE OR DELETE ON reward_refund_allocations FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TABLE reward_referral_reviews (
 attribution_id text PRIMARY KEY REFERENCES reward_referrals(attribution_id),
 state text NOT NULL CHECK(state IN ('held','cleared','blocked')),reason text NOT NULL,
 request_id text NOT NULL REFERENCES change_requests(id),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE reward_offer_claims (
 order_id text PRIMARY KEY REFERENCES orders(id),offer_id text NOT NULL,policy_version_id text NOT NULL REFERENCES setting_versions(id),
 discount_kobo bigint NOT NULL CHECK(discount_kobo>0),customer_id text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX reward_offer_budget ON reward_offer_claims(policy_version_id,offer_id);
CREATE TRIGGER reward_offer_claims_immutable BEFORE UPDATE OR DELETE ON reward_offer_claims FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
ALTER TABLE reward_entry_details ADD COLUMN booking_id text REFERENCES service_bookings(id);
CREATE TABLE reward_service_jobs (
 booking_id text PRIMARY KEY REFERENCES service_bookings(id),policy_version_id text NOT NULL REFERENCES setting_versions(id),
 eligible_kobo bigint NOT NULL CHECK(eligible_kobo>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','review')),
 attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO setting_definitions(key,label,category,description,owner_role,risk,value_type,propose_roles,approve_roles,view_roles,required_roles,additional_verification) VALUES
('loyalty.referral_review','Referral risk review','Loyalty','Hold, clear or block a referral with evidence and independent owner/finance approval. Shared addresses are not proof of fraud.','owner',4,'referral_review','["owner","finance"]','["owner","finance"]','["owner","finance"]','["owner","finance"]',true);
INSERT INTO settings(key,scope,value) SELECT 'loyalty.referral_review',id,'{"attributionId":"","state":"held","reason":""}'::jsonb FROM branches;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['reward_refund_allocations','reward_referral_reviews','reward_offer_claims','reward_service_jobs'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN EXECUTE format('REVOKE ALL ON %I FROM anon',t); END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN EXECUTE format('REVOKE ALL ON %I FROM authenticated',t); END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN EXECUTE format('GRANT SELECT,INSERT ON %I TO easygas_server',t); END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT UPDATE(state,reason,request_id,updated_at) ON reward_referral_reviews TO easygas_server;
 GRANT UPDATE(status,attempts,last_error) ON reward_service_jobs TO easygas_server;
 END IF;
END $$;

ALTER TABLE credit_requests DROP CONSTRAINT credit_requests_amount_kobo_check;
ALTER TABLE credit_requests ADD CONSTRAINT credit_amount_valid CHECK(amount_kobo>=0 AND (kind='refund' OR amount_kobo>0));
CREATE FUNCTION preserve_refund_request_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.refund_lines IS NOT NULL AND (NEW.refund_lines,NEW.refund_fingerprint,NEW.refund_operation_key,NEW.amount_kobo,NEW.order_id,NEW.customer_id) IS DISTINCT FROM (OLD.refund_lines,OLD.refund_fingerprint,OLD.refund_operation_key,OLD.amount_kobo,OLD.order_id,OLD.customer_id) THEN RAISE EXCEPTION 'Refund request allocation is immutable'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER refund_request_source_immutable BEFORE UPDATE ON credit_requests FOR EACH ROW EXECUTE FUNCTION preserve_refund_request_source();
CREATE FUNCTION preserve_service_reward_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.booking_id,NEW.policy_version_id,NEW.eligible_kobo,NEW.created_at) IS DISTINCT FROM (OLD.booking_id,OLD.policy_version_id,OLD.eligible_kobo,OLD.created_at) THEN RAISE EXCEPTION 'Service reward source is immutable'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER service_reward_source_immutable BEFORE UPDATE ON reward_service_jobs FOR EACH ROW EXECUTE FUNCTION preserve_service_reward_source();

INSERT INTO schema_migrations(version) VALUES ('044');
-- Repair older local revision-044 iterations without changing existing records.
ALTER TABLE credit_requests DROP CONSTRAINT IF EXISTS credit_requests_amount_kobo_check;
ALTER TABLE credit_requests DROP CONSTRAINT IF EXISTS credit_amount_valid;
ALTER TABLE credit_requests ADD CONSTRAINT credit_amount_valid CHECK(amount_kobo>=0 AND (kind='refund' OR amount_kobo>0));
CREATE OR REPLACE FUNCTION preserve_refund_request_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.refund_lines IS NOT NULL AND (NEW.refund_lines,NEW.refund_fingerprint,NEW.refund_operation_key,NEW.amount_kobo,NEW.order_id,NEW.customer_id) IS DISTINCT FROM (OLD.refund_lines,OLD.refund_fingerprint,OLD.refund_operation_key,OLD.amount_kobo,OLD.order_id,OLD.customer_id) THEN RAISE EXCEPTION 'Refund request allocation is immutable'; END IF; RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER refund_request_source_immutable BEFORE UPDATE ON credit_requests FOR EACH ROW EXECUTE FUNCTION preserve_refund_request_source();
CREATE OR REPLACE FUNCTION preserve_service_reward_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.booking_id,NEW.policy_version_id,NEW.eligible_kobo,NEW.created_at) IS DISTINCT FROM (OLD.booking_id,OLD.policy_version_id,OLD.eligible_kobo,OLD.created_at) THEN RAISE EXCEPTION 'Service reward source is immutable'; END IF; RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER service_reward_source_immutable BEFORE UPDATE ON reward_service_jobs FOR EACH ROW EXECUTE FUNCTION preserve_service_reward_source();
CREATE TABLE reward_offer_notices(id text PRIMARY KEY,customer_id text NOT NULL REFERENCES users(id),offer_id text NOT NULL,policy_version_id text NOT NULL REFERENCES setting_versions(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reward_notice_frequency ON reward_offer_notices(customer_id,offer_id,created_at);
CREATE TRIGGER reward_offer_notices_immutable BEFORE UPDATE OR DELETE ON reward_offer_notices FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
ALTER TABLE reward_offer_notices ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON reward_offer_notices FROM anon; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON reward_offer_notices FROM authenticated; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN GRANT SELECT,INSERT ON reward_offer_notices TO easygas_server; END IF;
END $$;

INSERT INTO schema_migrations(version) VALUES ('045');
-- Trusted server connections still use application ownership/role checks.
-- A grant alone cannot pass RLS: explicitly permit only the existing NOLOGIN runtime role.
DO $$ DECLARE t text; BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN CREATE ROLE easygas_server NOLOGIN; END IF;
 FOREACH t IN ARRAY ARRAY['reward_entry_details','reward_jobs','reward_order_discounts','reward_referral_codes','reward_referrals','reward_refund_allocations','reward_referral_reviews','reward_offer_claims','reward_service_jobs','reward_offer_notices'] LOOP
 IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname=current_schema() AND tablename=t AND policyname='trusted_server') THEN
 EXECUTE format('CREATE POLICY trusted_server ON %I TO easygas_server USING(true) WITH CHECK(true)',t);
 END IF;
 END LOOP;
END $$;

INSERT INTO schema_migrations(version) VALUES ('046');
-- Additive identity and assisted-order attribution; no invented customers or contact data.
ALTER TABLE users ADD COLUMN public_customer_id text;
ALTER TABLE users ADD COLUMN contact_phone text;
ALTER TABLE users ADD COLUMN phone_verified_at timestamptz;
ALTER TABLE users ADD COLUMN onboarding_version integer NOT NULL DEFAULT 0 CHECK(onboarding_version>=0);
ALTER TABLE users ADD COLUMN provisional boolean NOT NULL DEFAULT false;
UPDATE users SET public_customer_id='EGC-'||upper(replace(gen_random_uuid()::text,'-','')) WHERE role IN ('customer','commercial');
CREATE UNIQUE INDEX users_public_customer_id_unique ON users(public_customer_id) WHERE public_customer_id IS NOT NULL;
CREATE INDEX users_contact_phone_lookup ON users(contact_phone) WHERE contact_phone IS NOT NULL;
ALTER TABLE users ADD CONSTRAINT users_contact_phone_format CHECK(contact_phone IS NULL OR contact_phone ~ '^\+234[789][01][0-9]{8}$');
CREATE FUNCTION customer_public_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='UPDATE' AND OLD.public_customer_id IS NOT NULL AND NEW.public_customer_id IS DISTINCT FROM OLD.public_customer_id THEN RAISE EXCEPTION 'Public customer identity is immutable'; END IF;
 IF NEW.role IN ('customer','commercial') AND NEW.public_customer_id IS NULL THEN NEW.public_customer_id='EGC-'||upper(replace(gen_random_uuid()::text,'-','')); END IF;
 IF TG_OP='UPDATE' AND NEW.contact_phone IS DISTINCT FROM OLD.contact_phone THEN NEW.phone_verified_at=NULL; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER customer_public_identity_guard BEFORE INSERT OR UPDATE ON users FOR EACH ROW EXECUTE FUNCTION customer_public_identity_guard();
ALTER TABLE orders ADD COLUMN order_source text NOT NULL DEFAULT 'LEGACY' CHECK(order_source IN ('LEGACY','WEB','MOBILE','PHONE_ASSISTED'));
ALTER TABLE orders ADD COLUMN assisted_by text REFERENCES users(id);
ALTER TABLE orders ADD COLUMN assisted_reason text;
ALTER TABLE orders ADD CONSTRAINT assisted_attribution_required CHECK((order_source='PHONE_ASSISTED' AND assisted_by IS NOT NULL AND length(assisted_reason)>=10) OR (order_source<>'PHONE_ASSISTED' AND assisted_by IS NULL));
CREATE FUNCTION preserve_assisted_attribution() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.order_source,NEW.assisted_by,NEW.assisted_reason) IS DISTINCT FROM (OLD.order_source,OLD.assisted_by,OLD.assisted_reason) THEN RAISE EXCEPTION 'Order source attribution is immutable'; END IF;
 RETURN NEW;
END $$;
-- Attribution is set in the original INSERT, never patched over an issued order.
CREATE TRIGGER preserve_assisted_attribution BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION preserve_assisted_attribution();
CREATE INDEX account_addresses_normalised_phone_lookup ON account_addresses ((regexp_replace(phone,'[^0-9]','','g'))) WHERE archived=false;

INSERT INTO schema_migrations(version) VALUES ('047');
-- Invoices snapshot existing order/ledger data; this migration does not create payments.
CREATE SEQUENCE customer_invoice_number_seq;
CREATE TABLE customer_invoices(
 id text PRIMARY KEY, invoice_number text NOT NULL UNIQUE DEFAULT ('EGI-'||lpad(nextval('customer_invoice_number_seq')::text,10,'0')),
 order_id text NOT NULL UNIQUE REFERENCES orders(id), customer_id text NOT NULL REFERENCES users(id), branch_id text NOT NULL REFERENCES branches(id),
 version integer NOT NULL DEFAULT 1 CHECK(version=1), currency text NOT NULL DEFAULT 'NGN' CHECK(currency='NGN'),
 total_kobo bigint NOT NULL CHECK(total_kobo>0), snapshot jsonb NOT NULL,
 issued_by text NOT NULL REFERENCES users(id), issued_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION preserve_customer_invoice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Issued invoice is immutable; use an authorised linked adjustment'; END $$;
CREATE TRIGGER customer_invoice_immutable BEFORE UPDATE OR DELETE ON customer_invoices FOR EACH ROW EXECUTE FUNCTION preserve_customer_invoice();
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN GRANT SELECT,INSERT ON customer_invoices TO easygas_server; GRANT USAGE ON SEQUENCE customer_invoice_number_seq TO easygas_server; END IF; END $$;
CREATE INDEX customer_invoices_customer_history ON customer_invoices(customer_id,issued_at DESC);
CREATE INDEX customer_invoices_branch_history ON customer_invoices(branch_id,issued_at DESC);

INSERT INTO schema_migrations(version) VALUES ('048');
-- Additive hardening also upgrades any development installation that recorded 048 early.
CREATE INDEX IF NOT EXISTS customer_invoices_customer_history ON customer_invoices(customer_id,issued_at DESC);
CREATE INDEX IF NOT EXISTS customer_invoices_branch_history ON customer_invoices(branch_id,issued_at DESC);
CREATE INDEX IF NOT EXISTS account_addresses_normalised_phone_lookup ON account_addresses ((regexp_replace(phone,'[^0-9]','','g'))) WHERE archived=false;
ALTER TABLE customer_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE customer_invoices FORCE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT ON customer_invoices TO easygas_server;
 GRANT USAGE ON SEQUENCE customer_invoice_number_seq TO easygas_server;
 CREATE POLICY customer_invoice_trusted_server ON customer_invoices TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;

INSERT INTO schema_migrations(version) VALUES ('049');
-- Additive operations workflows. No imported history, provider activation or balance edits.
CREATE TABLE phone_activations (
 id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, order_id text NOT NULL REFERENCES orders(id), customer_id text NOT NULL REFERENCES users(id),
 phone text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, consumed_at timestamptz,
 otp_hash text, otp_expires_at timestamptz, otp_attempts integer NOT NULL DEFAULT 0, sent_at timestamptz,
 verified_at timestamptz, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX phone_activation_customer ON phone_activations(customer_id,created_at DESC);
CREATE TABLE invoice_notes (
 id text PRIMARY KEY, invoice_id text NOT NULL REFERENCES customer_invoices(id), sequence integer NOT NULL,
 kind text NOT NULL CHECK(kind IN ('credit','debit','void')), amount_kobo bigint NOT NULL CHECK(amount_kobo>0),
 reason text NOT NULL, requested_by text NOT NULL REFERENCES users(id), approved_by text REFERENCES users(id),
 state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')),
 created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, UNIQUE(invoice_id,sequence),
 CHECK(approved_by IS NULL OR approved_by<>requested_by)
);
CREATE TABLE invoice_note_events(id text PRIMARY KEY,note_id text NOT NULL REFERENCES invoice_notes(id),actor_id text NOT NULL REFERENCES users(id),detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER invoice_note_events_immutable BEFORE UPDATE OR DELETE ON invoice_note_events FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TABLE invoice_payment_requests (
 id text PRIMARY KEY, invoice_id text NOT NULL REFERENCES customer_invoices(id), invoice_version integer NOT NULL, token_hash text NOT NULL UNIQUE,
 amount_kobo bigint NOT NULL CHECK(amount_kobo>0),currency text NOT NULL DEFAULT 'NGN' CHECK(currency='NGN'),
 expires_at timestamptz NOT NULL, revoked_at timestamptz, created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX invoice_request_invoice ON invoice_payment_requests(invoice_id,created_at DESC);
CREATE TABLE driver_vehicles(id text PRIMARY KEY,branch_id text NOT NULL REFERENCES branches(id),label text NOT NULL,capacity_grams bigint NOT NULL CHECK(capacity_grams>0),lpg_suitable boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,estimated_litres_per_100km numeric CHECK(estimated_litres_per_100km>0));
CREATE TABLE driver_trips(id text PRIMARY KEY,driver_id text NOT NULL REFERENCES users(id),vehicle_id text NOT NULL REFERENCES driver_vehicles(id),branch_id text NOT NULL REFERENCES branches(id),start_odometer numeric NOT NULL CHECK(start_odometer>=0),end_odometer numeric CHECK(end_odometer>=start_odometer),location_consent boolean NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,version integer NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX driver_active_trip ON driver_trips(driver_id) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX vehicle_active_trip ON driver_trips(vehicle_id) WHERE ended_at IS NULL;
CREATE TABLE trip_events(id text PRIMARY KEY,trip_id text NOT NULL REFERENCES driver_trips(id),sequence integer NOT NULL CHECK(sequence>0),kind text NOT NULL CHECK(kind IN ('gps','fuel','status')),recorded_at timestamptz NOT NULL,payload jsonb NOT NULL,actor_id text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(trip_id,sequence));
CREATE TRIGGER trip_events_immutable BEFORE UPDATE OR DELETE ON trip_events FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE INDEX trip_event_history ON trip_events(trip_id,sequence);
CREATE TABLE dispatch_responses(id text PRIMARY KEY,attempt_id text NOT NULL UNIQUE REFERENCES delivery_attempts(id),driver_id text NOT NULL REFERENCES users(id),decision text NOT NULL CHECK(decision IN ('acknowledged','rejected')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER dispatch_responses_immutable BEFORE UPDATE OR DELETE ON dispatch_responses FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TABLE doorstep_amendments(id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),attempt_id text NOT NULL REFERENCES delivery_attempts(id),driver_id text NOT NULL REFERENCES users(id),order_version integer NOT NULL,proposal jsonb NOT NULL,price_snapshot jsonb NOT NULL,customer_consent_at timestamptz,state text NOT NULL DEFAULT 'proposed' CHECK(state IN ('proposed','consented','rejected','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX doorstep_order_history ON doorstep_amendments(order_id,created_at DESC);
CREATE TABLE delivery_photos(id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),attempt_id text NOT NULL REFERENCES delivery_attempts(id),actor_id text NOT NULL REFERENCES users(id),captured_at timestamptz NOT NULL DEFAULT now(),data bytea NOT NULL,sha256 text NOT NULL,alt text NOT NULL,consent boolean NOT NULL CHECK(consent),created_at timestamptz NOT NULL DEFAULT now(),retain_until timestamptz NOT NULL,UNIQUE(order_id,sha256));
CREATE INDEX delivery_photo_history ON delivery_photos(order_id,created_at DESC);
CREATE TRIGGER delivery_photos_immutable BEFORE UPDATE OR DELETE ON delivery_photos FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TABLE crm_followups(id text PRIMARY KEY,customer_id text NOT NULL REFERENCES users(id),branch_id text NOT NULL REFERENCES branches(id),owner_id text NOT NULL REFERENCES users(id),next_action text NOT NULL,due_at timestamptz NOT NULL,outcome text,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX crm_followup_due ON crm_followups(branch_id,due_at);
CREATE TABLE channel_consents(user_id text NOT NULL REFERENCES users(id),channel text NOT NULL CHECK(channel IN ('sms','whatsapp')),purpose text NOT NULL CHECK(purpose IN ('transactional','marketing','otp','refill')),enabled boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,evidence text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,channel,purpose));
ALTER TABLE message_outbox ADD COLUMN purpose text NOT NULL DEFAULT 'transactional' CHECK(purpose IN ('transactional','marketing','otp','refill'));
ALTER TABLE message_outbox ADD COLUMN provider_message_id text;
ALTER TABLE message_outbox ADD COLUMN delivery_status text;
ALTER TABLE message_outbox ADD COLUMN template_name text;
ALTER TABLE message_outbox ADD COLUMN lease_until timestamptz;
ALTER TABLE message_outbox ADD COLUMN consent_version integer;
ALTER TABLE message_outbox ADD COLUMN expires_at timestamptz;
CREATE UNIQUE INDEX channel_provider_message_id ON message_outbox(channel,provider_message_id) WHERE provider_message_id IS NOT NULL;
CREATE TABLE channel_receipts(id text PRIMARY KEY,channel text NOT NULL,provider_event_id text NOT NULL,provider_message_id text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(channel,provider_event_id));
CREATE TRIGGER channel_receipts_immutable BEFORE UPDATE OR DELETE ON channel_receipts FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['phone_activations','invoice_notes','invoice_note_events','invoice_payment_requests','driver_vehicles','driver_trips','trip_events','dispatch_responses','doorstep_amendments','delivery_photos','crm_followups','channel_consents','channel_receipts'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO easygas_server',t);
 EXECUTE format('CREATE POLICY trusted_server ON %I TO easygas_server USING(true) WITH CHECK(true)',t);
 END IF; END LOOP;
END $$;

ALTER TABLE delivery_attempts ADD COLUMN requires_ack boolean NOT NULL DEFAULT false;
CREATE FUNCTION invoice_note_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state<>'pending' THEN RAISE EXCEPTION 'Invoice note decisions are immutable'; END IF;
 IF (NEW.id,NEW.invoice_id,NEW.sequence,NEW.kind,NEW.amount_kobo,NEW.reason,NEW.requested_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.invoice_id,OLD.sequence,OLD.kind,OLD.amount_kobo,OLD.reason,OLD.requested_by,OLD.created_at) OR NEW.state NOT IN ('approved','rejected') OR NEW.approved_by IS NULL OR NEW.decided_at IS NULL THEN RAISE EXCEPTION 'Only an independent final note decision is permitted'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER invoice_notes_guard BEFORE UPDATE OR DELETE ON invoice_notes FOR EACH ROW EXECUTE FUNCTION invoice_note_guard();
CREATE FUNCTION doorstep_proposal_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state<>'proposed' OR NEW.state NOT IN ('consented','rejected','cancelled') OR (NEW.id,NEW.order_id,NEW.attempt_id,NEW.driver_id,NEW.order_version,NEW.proposal,NEW.price_snapshot,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.order_id,OLD.attempt_id,OLD.driver_id,OLD.order_version,OLD.proposal,OLD.price_snapshot,OLD.created_at) THEN RAISE EXCEPTION 'Doorstep proposal history is immutable'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER doorstep_proposal_history BEFORE UPDATE OR DELETE ON doorstep_amendments FOR EACH ROW EXECUTE FUNCTION doorstep_proposal_guard();
INSERT INTO setting_definitions(key,label,category,description,owner_role,risk,value_type,propose_roles,approve_roles,view_roles,required_roles,additional_verification)
VALUES('crm.retention','Retention and win-back policy','Marketing','Thresholds and conservative monthly message budget; default disabled','owner',3,'crm_retention','["owner","manager"]','["owner","finance"]','["owner","manager","sales","finance"]','["finance"]',true);
INSERT INTO settings(key,scope,value) SELECT 'crm.retention',id,'{"enabled":false,"atRiskDays":45,"dormantDays":90,"monthlyBudgetKobo":0,"costCeilingPerMessageKobo":0}'::jsonb FROM branches;

INSERT INTO schema_migrations(version) VALUES ('050');
-- Preserve immutable evidence metadata and hash. Only expired image bytes may be purged.
CREATE FUNCTION preserve_delivery_photo() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='UPDATE' AND OLD.retain_until<=now() AND octet_length(OLD.data)>0 AND octet_length(NEW.data)=0 AND (to_jsonb(NEW)-'data')=(to_jsonb(OLD)-'data') THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Delivery photo history is immutable; only expired image bytes may be purged';
END $$;
DROP TRIGGER delivery_photos_immutable ON delivery_photos;
CREATE TRIGGER delivery_photos_immutable BEFORE UPDATE OR DELETE ON delivery_photos FOR EACH ROW EXECUTE FUNCTION preserve_delivery_photo();
CREATE INDEX delivery_photo_expiration ON delivery_photos(retain_until) WHERE octet_length(data)>0;

INSERT INTO schema_migrations(version) VALUES ('051');
-- Additive capabilities on canonical identities/sessions; no parallel driver model.
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS driver_delivery_only boolean NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS driver_available boolean NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS driver_availability_updated_at timestamptz;
CREATE INDEX IF NOT EXISTS driver_owned_history ON orders(driver_id,created_at DESC) WHERE driver_id IS NOT NULL;

