-- Assessment and chargeable work remain phases of the canonical booking.
ALTER TABLE service_bookings ADD COLUMN work_phase text NOT NULL DEFAULT 'assessment' CHECK(work_phase IN ('assessment','authorised','paused'));
ALTER TABLE service_bookings ADD COLUMN work_quote_id text REFERENCES service_quotes(id);
ALTER TABLE users ADD COLUMN technician_available boolean NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN technician_availability_updated_at timestamptz;

INSERT INTO schema_migrations(version) VALUES ('053');
ALTER TABLE sessions ADD COLUMN technician_service_only boolean NOT NULL DEFAULT false;

INSERT INTO schema_migrations(version) VALUES ('054');
ALTER TABLE service_bookings ADD COLUMN work_started_at timestamptz;
ALTER TABLE media_assets ADD COLUMN service_photo_consent boolean NOT NULL DEFAULT false;
ALTER TABLE media_assets ADD COLUMN service_retain_until timestamptz;
ALTER TABLE media_assets ADD COLUMN service_sha256 text;
CREATE UNIQUE INDEX service_proof_content_once ON media_assets(booking_id,owner_id,service_sha256) WHERE booking_id IS NOT NULL AND service_sha256 IS NOT NULL;

INSERT INTO schema_migrations(version) VALUES ('055');
ALTER TABLE service_bookings ADD COLUMN assignment_response text NOT NULL DEFAULT 'pending' CHECK(assignment_response IN ('pending','acknowledged','declined'));
ALTER TABLE service_bookings ADD COLUMN assignment_response_reason text;

INSERT INTO schema_migrations(version) VALUES ('056');
-- Additive, default-disabled sandbox infrastructure. No backfill or financial posting.
CREATE TABLE payment_intents(
 id text PRIMARY KEY,customer_id text NOT NULL REFERENCES users(id),branch_id text NOT NULL REFERENCES branches(id),
 purpose text NOT NULL CHECK(purpose IN ('invoice','service','wallet')),invoice_id text REFERENCES customer_invoices(id),booking_id text REFERENCES service_bookings(id),
 request_key text NOT NULL,request_hash text NOT NULL,obligation_version text NOT NULL,quote jsonb NOT NULL,email_snapshot text NOT NULL,
 status text NOT NULL DEFAULT 'quoted' CHECK(status IN ('quoted','pending','paid','failed','expired','under_review')),
 expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(customer_id,request_key),CHECK((purpose='invoice' AND invoice_id IS NOT NULL AND booking_id IS NULL) OR (purpose='service' AND booking_id IS NOT NULL AND invoice_id IS NULL) OR (purpose='wallet' AND invoice_id IS NULL AND booking_id IS NULL))
);
CREATE INDEX payment_intents_customer ON payment_intents(customer_id,created_at DESC);
CREATE INDEX payment_intents_invoice ON payment_intents(invoice_id) WHERE invoice_id IS NOT NULL;
CREATE INDEX payment_intents_booking ON payment_intents(booking_id) WHERE booking_id IS NOT NULL;
CREATE TABLE payment_attempts(
 id text PRIMARY KEY,intent_id text NOT NULL UNIQUE REFERENCES payment_intents(id),provider text NOT NULL DEFAULT 'paystack' CHECK(provider='paystack'),environment text NOT NULL CHECK(environment='test'),reference text NOT NULL UNIQUE,
 state text NOT NULL DEFAULT 'prepared' CHECK(state IN ('prepared','initializing','awaiting_customer','pending','verified_paid','failed','abandoned','under_review')),
 checkout_url text,initialization_started_at timestamptz,last_checked_at timestamptz,reconcile_after timestamptz NOT NULL DEFAULT now(),retry_count integer NOT NULL DEFAULT 0,provider_id text UNIQUE,actual_fee_kobo bigint CHECK(actual_fee_kobo>=0),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payment_attempts_reconcile ON payment_attempts(reconcile_after,id) WHERE state IN ('initializing','awaiting_customer','pending');
CREATE TABLE payment_provider_events(
 id text PRIMARY KEY,digest text NOT NULL UNIQUE,event_key text NOT NULL UNIQUE,event_type text NOT NULL,reference text NOT NULL,attempt_id text REFERENCES payment_attempts(id),
 signature_mode text NOT NULL CHECK(signature_mode IN ('timestamped','legacy')),state text NOT NULL DEFAULT 'received' CHECK(state IN ('received','processed','under_review')),received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz
);
CREATE INDEX payment_provider_events_pending ON payment_provider_events(received_at,id) WHERE state='received';
CREATE TABLE payment_postings(
 id text PRIMARY KEY,intent_id text NOT NULL UNIQUE REFERENCES payment_intents(id),attempt_id text NOT NULL UNIQUE REFERENCES payment_attempts(id),provider_reference text NOT NULL UNIQUE,
 base_kobo bigint NOT NULL CHECK(base_kobo>0),customer_fee_kobo bigint NOT NULL CHECK(customer_fee_kobo>=0),gross_kobo bigint NOT NULL CHECK(gross_kobo=base_kobo+customer_fee_kobo),actual_fee_kobo bigint CHECK(actual_fee_kobo>=0),
 verified_payment_id text UNIQUE REFERENCES verified_payments(id),wallet_entry_id text UNIQUE REFERENCES wallet_entries(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK((verified_payment_id IS NOT NULL)::int+(wallet_entry_id IS NOT NULL)::int=1)
);
CREATE TRIGGER payment_postings_immutable BEFORE UPDATE OR DELETE ON payment_postings FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TABLE payment_exceptions(id text PRIMARY KEY,attempt_id text REFERENCES payment_attempts(id),category text NOT NULL,detail text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','resolved')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(attempt_id,category));
CREATE FUNCTION preserve_payment_quote() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.id<>OLD.id OR NEW.created_at<>OLD.created_at OR NEW.customer_id<>OLD.customer_id OR NEW.branch_id<>OLD.branch_id OR NEW.purpose<>OLD.purpose OR NEW.invoice_id IS DISTINCT FROM OLD.invoice_id OR NEW.booking_id IS DISTINCT FROM OLD.booking_id OR NEW.request_key<>OLD.request_key OR NEW.request_hash<>OLD.request_hash OR NEW.obligation_version<>OLD.obligation_version OR NEW.quote<>OLD.quote OR NEW.email_snapshot<>OLD.email_snapshot OR NEW.expires_at<>OLD.expires_at THEN RAISE EXCEPTION 'Payment obligation and fee quote are immutable'; END IF;RETURN NEW;END $$;
CREATE TRIGGER payment_quote_immutable BEFORE UPDATE ON payment_intents FOR EACH ROW EXECUTE FUNCTION preserve_payment_quote();
CREATE TRIGGER payment_intent_no_delete BEFORE DELETE ON payment_intents FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
INSERT INTO setting_definitions(key,label,category,description,owner_role,risk,value_type,propose_roles,approve_roles,view_roles,required_roles,additional_verification)
VALUES('payment.gateway','Payment Gateway & Fees','Wallet & Payments','Sandbox only. Independently approved fee versions and funding controls; secrets remain server-side. Live activation is unsupported.','finance',4,'payment_gateway','["owner","finance"]','["owner","finance"]','["owner","finance"]','["owner","finance"]',true);
INSERT INTO settings(key,scope,value) SELECT 'payment.gateway',id,'{"enabled":false,"environment":"test","channels":[],"fee":null,"providerAutomaticFees":"unknown","passThroughApproved":false,"merchantApprovalReference":"","quoteLifetimeSeconds":600,"walletFunding":false,"walletMinimumKobo":10000,"walletMaximumKobo":10000000,"partialInvoices":false}'::jsonb FROM branches;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['payment_intents','payment_attempts','payment_provider_events','payment_postings','payment_exceptions'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO easygas_server',t);EXECUTE format('CREATE POLICY server_only ON %I TO easygas_server USING(true) WITH CHECK(true)',t);END IF;
 END LOOP; END $$;

CREATE FUNCTION preserve_payment_attempt_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.intent_id<>OLD.intent_id OR NEW.provider<>OLD.provider OR NEW.environment<>OLD.environment OR NEW.reference<>OLD.reference OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION 'Payment attempt identity is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER payment_attempt_identity BEFORE UPDATE ON payment_attempts FOR EACH ROW EXECUTE FUNCTION preserve_payment_attempt_identity();
CREATE TRIGGER payment_attempt_no_delete BEFORE DELETE ON payment_attempts FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();

INSERT INTO schema_migrations(version) VALUES ('057');
-- Branch mass remains canonical and inclusive of vehicle custody. No opening balances.
CREATE TABLE bulk_lpg_meters (
 id text PRIMARY KEY,vehicle_id text NOT NULL REFERENCES driver_vehicles(id),serial text NOT NULL UNIQUE,
 calibration_reference text NOT NULL,calibration_expires_at timestamptz NOT NULL,
 unit text NOT NULL DEFAULT 'grams' CHECK(unit='grams'),active boolean NOT NULL DEFAULT true,
 recorded_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE bulk_lpg_loads (
 id text PRIMARY KEY,trip_id text NOT NULL UNIQUE REFERENCES driver_trips(id),meter_id text NOT NULL REFERENCES bulk_lpg_meters(id),
 branch_id text NOT NULL REFERENCES branches(id),loaded_grams bigint NOT NULL CHECK(loaded_grams>0),
 buffer_grams bigint NOT NULL CHECK(buffer_grams>=0 AND buffer_grams<=loaded_grams),
 dispensed_grams bigint NOT NULL DEFAULT 0 CHECK(dispensed_grams>=0 AND dispensed_grams<=loaded_grams),
 meter_reading_grams bigint NOT NULL CHECK(meter_reading_grams>=0),
 issued_by text NOT NULL REFERENCES users(id),acknowledged_by text REFERENCES users(id),received_by text REFERENCES users(id),
 state text NOT NULL DEFAULT 'issued' CHECK(state IN ('issued','active','returning','held','reconciled')),
 declared_return_grams bigint CHECK(declared_return_grams>=0),version integer NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT now(),CHECK(acknowledged_by IS NULL OR acknowledged_by<>issued_by),
 CHECK(received_by IS NULL OR received_by<>acknowledged_by)
);
CREATE TABLE bulk_lpg_allocations (
 order_id text PRIMARY KEY REFERENCES orders(id),load_id text NOT NULL REFERENCES bulk_lpg_loads(id),
 grams bigint NOT NULL CHECK(grams>0),dispensed_grams bigint NOT NULL DEFAULT 0 CHECK(dispensed_grams>=0 AND dispensed_grams<=grams),
 state text NOT NULL DEFAULT 'allocated' CHECK(state IN ('allocated','dispensed','released','returned','fulfilled'))
);
CREATE INDEX bulk_lpg_allocations_load ON bulk_lpg_allocations(load_id);
CREATE TABLE bulk_lpg_events (
 id text PRIMARY KEY,load_id text NOT NULL REFERENCES bulk_lpg_loads(id),order_id text REFERENCES orders(id),
 kind text NOT NULL,actor_id text NOT NULL REFERENCES users(id),detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX bulk_lpg_events_history ON bulk_lpg_events(load_id,created_at,id);
CREATE TRIGGER bulk_lpg_events_immutable BEFORE UPDATE OR DELETE ON bulk_lpg_events FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['bulk_lpg_meters','bulk_lpg_loads','bulk_lpg_allocations','bulk_lpg_events'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO easygas_server',t);
 EXECUTE format('CREATE POLICY server_only ON %I TO easygas_server USING(true) WITH CHECK(true)',t);END IF;
 END LOOP; END $$;

INSERT INTO schema_migrations(version) VALUES ('058');
-- Keep measured custody recovery distinct from generic stock adjustments.
-- No opening quantities, balances, measurements or approvals are created.
ALTER TABLE inventory_operations DROP CONSTRAINT inventory_operations_kind_check;
ALTER TABLE inventory_operations ADD CONSTRAINT inventory_operations_kind_check
 CHECK(kind IN ('adjustment','stocktake','quarantine','return_release','threshold','purchase','transfer','expense','expense_reversal','hold_disposition','bulk_return_recovery'));

INSERT INTO schema_migrations(version) VALUES ('059');
-- Supplementary gas stays attached to the original order, invoice and vehicle.
CREATE TABLE doorstep_execution (
 amendment_id text PRIMARY KEY REFERENCES doorstep_amendments(id),
 order_id text NOT NULL REFERENCES orders(id),load_id text NOT NULL REFERENCES bulk_lpg_loads(id),
 note_id text NOT NULL UNIQUE REFERENCES invoice_notes(id),credit_note_id text UNIQUE REFERENCES invoice_notes(id),
 grams bigint NOT NULL CHECK(grams>0),amount_kobo bigint NOT NULL CHECK(amount_kobo>0),
 cylinder_id text NOT NULL REFERENCES cylinders(id),allowable_grams bigint NOT NULL CHECK(allowable_grams>=grams),
 inspected_by text NOT NULL REFERENCES users(id),inspection_evidence text NOT NULL,
 expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','dispensed','cancelled')),
 cash_reported_by text REFERENCES users(id),cash_reported_at timestamptz,
 cash_verified_by text REFERENCES users(id),cash_verified_at timestamptz,
 CHECK(cash_verified_by IS NULL OR (cash_reported_by IS NOT NULL AND cash_verified_by<>cash_reported_by))
);
CREATE UNIQUE INDEX doorstep_one_reserved_order ON doorstep_execution(order_id) WHERE state='reserved';
CREATE UNIQUE INDEX doorstep_one_reserved_cylinder ON doorstep_execution(cylinder_id) WHERE state='reserved';
CREATE INDEX doorstep_load_pending ON doorstep_execution(load_id,state);
CREATE FUNCTION preserve_doorstep_execution() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state<>'reserved' THEN RAISE EXCEPTION 'Doorstep execution history is immutable'; END IF;
 IF (NEW.amendment_id,NEW.order_id,NEW.load_id,NEW.note_id,NEW.grams,NEW.amount_kobo,NEW.cylinder_id,NEW.allowable_grams,NEW.inspected_by,NEW.inspection_evidence,NEW.expires_at,NEW.created_at)
 IS DISTINCT FROM (OLD.amendment_id,OLD.order_id,OLD.load_id,OLD.note_id,OLD.grams,OLD.amount_kobo,OLD.cylinder_id,OLD.allowable_grams,OLD.inspected_by,OLD.inspection_evidence,OLD.expires_at,OLD.created_at)
 OR (OLD.cash_reported_by IS NOT NULL AND (NEW.cash_reported_by,NEW.cash_reported_at) IS DISTINCT FROM (OLD.cash_reported_by,OLD.cash_reported_at))
 OR (OLD.cash_verified_by IS NOT NULL AND (NEW.cash_verified_by,NEW.cash_verified_at) IS DISTINCT FROM (OLD.cash_verified_by,OLD.cash_verified_at))
 OR (OLD.credit_note_id IS NOT NULL AND NEW.credit_note_id IS DISTINCT FROM OLD.credit_note_id)
 THEN RAISE EXCEPTION 'Doorstep obligation and collection evidence is immutable'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER doorstep_execution_guard BEFORE UPDATE OR DELETE ON doorstep_execution FOR EACH ROW EXECUTE FUNCTION preserve_doorstep_execution();
ALTER TABLE doorstep_execution ENABLE ROW LEVEL SECURITY;
ALTER TABLE doorstep_execution FORCE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT,UPDATE ON doorstep_execution TO easygas_server;
 CREATE POLICY server_only ON doorstep_execution TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;

INSERT INTO schema_migrations(version) VALUES ('060');
-- Extend the existing immutable invoice system; no new customer/payment ledger.
ALTER TABLE customer_invoices ALTER COLUMN order_id DROP NOT NULL;
ALTER TABLE customer_invoices ADD COLUMN booking_id text UNIQUE REFERENCES service_bookings(id);
ALTER TABLE customer_invoices ADD CONSTRAINT invoice_exactly_one_source CHECK ((order_id IS NOT NULL)::int + (booking_id IS NOT NULL)::int = 1);
CREATE INDEX customer_invoices_booking ON customer_invoices(booking_id) WHERE booking_id IS NOT NULL;

-- Bind secure requests to the approved quote/report identity, including equal-price scope changes.
ALTER TABLE invoice_payment_requests ADD COLUMN service_source_key text;

-- Preserve the existing independently reviewed full-service refund path.
-- Excess-only reconciliation is explicit and cannot silently reverse earned charges/rewards.
ALTER TABLE credit_requests ADD COLUMN service_refund_scope text NOT NULL DEFAULT 'service' CHECK(service_refund_scope IN ('service','excess'));

INSERT INTO schema_migrations(version) VALUES ('061');
-- Revision history supplements the existing booking/invoice, never a collectible ledger.
CREATE TABLE service_invoice_drafts (
 id text PRIMARY KEY,
 booking_id text NOT NULL REFERENCES service_bookings(id),
 revision integer NOT NULL CHECK(revision>0),
 source_key text NOT NULL,
 source_total_kobo bigint NOT NULL CHECK(source_total_kobo>0),
 due_date date NOT NULL,
 customer_note text NOT NULL CHECK(length(customer_note)<=2000),
 reason text NOT NULL,
 created_by text NOT NULL REFERENCES users(id),
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(booking_id,revision)
);
CREATE TRIGGER service_invoice_draft_immutable BEFORE UPDATE OR DELETE ON service_invoice_drafts FOR EACH ROW EXECUTE FUNCTION preserve_customer_invoice();
ALTER TABLE service_invoice_drafts ENABLE ROW LEVEL SECURITY;
ALTER TABLE service_invoice_drafts FORCE ROW LEVEL SECURITY;
REVOKE ALL ON service_invoice_drafts FROM PUBLIC;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT ON service_invoice_drafts TO easygas_server;
 CREATE POLICY service_invoice_draft_trusted_server ON service_invoice_drafts TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;

INSERT INTO schema_migrations(version) VALUES ('062');
-- Route planning evidence only: does not alter orders, delivery charges or inventory.
CREATE TABLE dispatch_destinations (
 id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), branch_id text NOT NULL REFERENCES branches(id),
 revision integer NOT NULL CHECK(revision>0), address_hash text NOT NULL, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180),
 evidence text NOT NULL, confirmed_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,revision)
);
CREATE TABLE dispatch_route_estimates (
 id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), driver_id text NOT NULL REFERENCES users(id), branch_id text NOT NULL REFERENCES branches(id),
 trip_id text NOT NULL REFERENCES driver_trips(id), context_hash text NOT NULL, policy_version integer NOT NULL,
 provider text NOT NULL, metres double precision NOT NULL CHECK(metres>=0), seconds double precision NOT NULL CHECK(seconds>=0), operating_kobo bigint NOT NULL CHECK(operating_kobo>=0),
 plan jsonb NOT NULL, expires_at timestamptz NOT NULL, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX dispatch_route_current ON dispatch_route_estimates(order_id,driver_id,created_at DESC);
CREATE TRIGGER dispatch_destination_immutable BEFORE UPDATE OR DELETE ON dispatch_destinations FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TRIGGER dispatch_route_immutable BEFORE UPDATE OR DELETE ON dispatch_route_estimates FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
ALTER TABLE dispatch_destinations ENABLE ROW LEVEL SECURITY;
ALTER TABLE dispatch_destinations FORCE ROW LEVEL SECURITY;
ALTER TABLE dispatch_route_estimates ENABLE ROW LEVEL SECURITY;
ALTER TABLE dispatch_route_estimates FORCE ROW LEVEL SECURITY;
REVOKE ALL ON dispatch_destinations,dispatch_route_estimates FROM PUBLIC;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT ON dispatch_destinations,dispatch_route_estimates TO easygas_server;
 CREATE POLICY trusted_server ON dispatch_destinations TO easygas_server USING(true) WITH CHECK(true);
 CREATE POLICY trusted_server ON dispatch_route_estimates TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;
INSERT INTO setting_definitions(key,label,category,description,owner_role,risk,value_type,propose_roles,approve_roles,view_roles,required_roles,additional_verification)
VALUES('dispatch.routing','Road routing and operating-cost policy','Delivery','Independently approved route-planning rates and stop allowance. Estimates never change customer fees. Default disabled.','owner',3,'dispatch_routing','["owner","manager","dispatcher"]','["owner","finance"]','["owner","manager","dispatcher","finance"]','["finance"]',true);
INSERT INTO settings(key,scope,value) SELECT 'dispatch.routing',id,'{"enabled":false,"fuelKoboPerLitre":null,"operatingKoboPerKm":null,"stopMinutes":null,"maxSnapMetres":null}'::jsonb FROM branches;

INSERT INTO schema_migrations(version) VALUES ('063');
-- Per-cylinder evidence extends the existing supplementary obligation; no duplicate order/ledger.
CREATE TABLE doorstep_cylinder_lines (
 id text PRIMARY KEY, amendment_id text NOT NULL REFERENCES doorstep_execution(amendment_id),
 position integer NOT NULL CHECK(position BETWEEN 1 AND 10), cylinder_id text NOT NULL REFERENCES cylinders(id),
 grams bigint NOT NULL CHECK(grams>0), capacity_grams bigint NOT NULL CHECK(capacity_grams>=grams),
 amount_kobo bigint NOT NULL CHECK(amount_kobo>0), allowable_grams bigint NOT NULL CHECK(allowable_grams>=grams AND allowable_grams<=capacity_grams),
 inspected_by text NOT NULL REFERENCES users(id), evidence text NOT NULL,
 state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','dispensed','cancelled')),
 meter_reading_grams bigint CHECK(meter_reading_grams>=0), recorded_by text REFERENCES users(id), recorded_at timestamptz,
 UNIQUE(amendment_id,position), UNIQUE(amendment_id,cylinder_id),
 CHECK((state='dispensed')=(meter_reading_grams IS NOT NULL AND recorded_by IS NOT NULL AND recorded_at IS NOT NULL))
);
CREATE UNIQUE INDEX doorstep_cylinder_pending ON doorstep_cylinder_lines(cylinder_id) WHERE state='reserved';
CREATE FUNCTION preserve_doorstep_cylinder_line() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state<>'reserved' OR
 (NEW.id,NEW.amendment_id,NEW.position,NEW.cylinder_id,NEW.grams,NEW.capacity_grams,NEW.amount_kobo,NEW.allowable_grams,NEW.inspected_by,NEW.evidence)
 IS DISTINCT FROM (OLD.id,OLD.amendment_id,OLD.position,OLD.cylinder_id,OLD.grams,OLD.capacity_grams,OLD.amount_kobo,OLD.allowable_grams,OLD.inspected_by,OLD.evidence)
 THEN RAISE EXCEPTION 'Cylinder obligation and fulfilled evidence are immutable'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER doorstep_cylinder_guard BEFORE UPDATE OR DELETE ON doorstep_cylinder_lines FOR EACH ROW EXECUTE FUNCTION preserve_doorstep_cylinder_line();
ALTER TABLE doorstep_cylinder_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE doorstep_cylinder_lines FORCE ROW LEVEL SECURITY;
REVOKE ALL ON doorstep_cylinder_lines FROM PUBLIC;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT,UPDATE ON doorstep_cylinder_lines TO easygas_server;
 CREATE POLICY server_only ON doorstep_cylinder_lines TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;

INSERT INTO schema_migrations(version) VALUES ('064');
-- Excess collection is a governed purchase-credit refund, never a second payment or sale refund.
ALTER TABLE credit_requests ADD COLUMN invoice_excess boolean NOT NULL DEFAULT false;
ALTER TABLE credit_requests ADD COLUMN invoice_excess_snapshot jsonb;
ALTER TABLE credit_requests ADD CONSTRAINT invoice_excess_source CHECK(NOT invoice_excess OR (order_id IS NOT NULL AND booking_id IS NULL AND kind='refund' AND invoice_excess_snapshot IS NOT NULL));

INSERT INTO schema_migrations(version) VALUES ('065');
-- Canonical branch inventory remains inclusive of measured vehicle custody.
ALTER TABLE driver_vehicles ADD COLUMN physical_capacity_grams bigint CHECK(physical_capacity_grams>0);
CREATE TABLE vehicle_product_loads (
 id text PRIMARY KEY,trip_id text NOT NULL REFERENCES driver_trips(id),branch_id text NOT NULL REFERENCES branches(id),product_id text NOT NULL REFERENCES products(id),
 quantity integer NOT NULL CHECK(quantity>0),unit_weight_grams bigint NOT NULL CHECK(unit_weight_grams>0),
 available integer NOT NULL CHECK(available>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0),handed integer NOT NULL DEFAULT 0 CHECK(handed>=0),
 returned integer NOT NULL DEFAULT 0 CHECK(returned>=0),removed integer NOT NULL DEFAULT 0 CHECK(removed>=0),
 issued_by text NOT NULL REFERENCES users(id),acknowledged_by text REFERENCES users(id),received_by text REFERENCES users(id),
 state text NOT NULL DEFAULT 'issued' CHECK(state IN ('issued','active','returning','held','reconciled')),version integer NOT NULL DEFAULT 1,
 evidence text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(quantity=available+reserved+handed+returned+removed),CHECK(acknowledged_by IS NULL OR acknowledged_by<>issued_by),CHECK(received_by IS NULL OR received_by<>acknowledged_by)
);
CREATE TABLE vehicle_product_serials (
 id text PRIMARY KEY,load_id text NOT NULL REFERENCES vehicle_product_loads(id),cylinder_id text NOT NULL REFERENCES cylinders(id),
 state text NOT NULL DEFAULT 'loaded' CHECK(state IN ('loaded','reserved','handed','returned','quarantined')),amendment_id text REFERENCES doorstep_amendments(id),UNIQUE(load_id,cylinder_id)
);
CREATE UNIQUE INDEX vehicle_serial_custody ON vehicle_product_serials(cylinder_id) WHERE state IN ('loaded','reserved');
CREATE TABLE vehicle_product_events(id text PRIMARY KEY,load_id text NOT NULL REFERENCES vehicle_product_loads(id),order_id text REFERENCES orders(id),kind text NOT NULL,actor_id text NOT NULL REFERENCES users(id),detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER vehicle_product_events_immutable BEFORE UPDATE OR DELETE ON vehicle_product_events FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TABLE doorstep_product_execution(
 amendment_id text PRIMARY KEY REFERENCES doorstep_amendments(id),order_id text NOT NULL REFERENCES orders(id),trip_id text NOT NULL REFERENCES driver_trips(id),note_id text NOT NULL UNIQUE REFERENCES invoice_notes(id),credit_note_id text UNIQUE REFERENCES invoice_notes(id),
 amount_kobo bigint NOT NULL CHECK(amount_kobo>0),state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','handed','cancelled')),
 expires_at timestamptz NOT NULL,cash_reported_by text REFERENCES users(id),cash_reported_at timestamptz,cash_verified_by text REFERENCES users(id),cash_verified_at timestamptz,
 CHECK(cash_verified_by IS NULL OR (cash_reported_by IS NOT NULL AND cash_verified_by<>cash_reported_by))
);
CREATE UNIQUE INDEX doorstep_product_pending ON doorstep_product_execution(order_id) WHERE state='reserved';
CREATE TABLE doorstep_product_lines(id text PRIMARY KEY,amendment_id text NOT NULL REFERENCES doorstep_product_execution(amendment_id),load_id text NOT NULL REFERENCES vehicle_product_loads(id),product_id text NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity>0),unit_price_kobo bigint NOT NULL CHECK(unit_price_kobo>0),name text NOT NULL,serialized boolean NOT NULL,state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','handed','cancelled')),UNIQUE(amendment_id,load_id));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['vehicle_product_loads','vehicle_product_serials','vehicle_product_events','doorstep_product_execution','doorstep_product_lines'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO easygas_server',t);EXECUTE format('CREATE POLICY server_only ON %I TO easygas_server USING(true) WITH CHECK(true)',t);END IF;
 END LOOP;END $$;

INSERT INTO schema_migrations(version) VALUES ('066');
ALTER TABLE vehicle_product_loads ADD COLUMN serialized boolean NOT NULL DEFAULT false;
CREATE FUNCTION preserve_vehicle_product_load() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state='reconciled' OR (NEW.id,NEW.trip_id,NEW.branch_id,NEW.product_id,NEW.quantity,NEW.unit_weight_grams,NEW.issued_by,NEW.evidence,NEW.created_at,NEW.serialized) IS DISTINCT FROM (OLD.id,OLD.trip_id,OLD.branch_id,OLD.product_id,OLD.quantity,OLD.unit_weight_grams,OLD.issued_by,OLD.evidence,OLD.created_at,OLD.serialized) OR (OLD.acknowledged_by IS NOT NULL AND NEW.acknowledged_by IS DISTINCT FROM OLD.acknowledged_by) THEN RAISE EXCEPTION 'Vehicle product custody history is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER vehicle_product_load_guard BEFORE UPDATE OR DELETE ON vehicle_product_loads FOR EACH ROW EXECUTE FUNCTION preserve_vehicle_product_load();
CREATE FUNCTION preserve_vehicle_product_serial() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state IN ('handed','returned','quarantined') OR (NEW.id,NEW.load_id,NEW.cylinder_id) IS DISTINCT FROM (OLD.id,OLD.load_id,OLD.cylinder_id) THEN RAISE EXCEPTION 'Vehicle serial history is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER vehicle_product_serial_guard BEFORE UPDATE OR DELETE ON vehicle_product_serials FOR EACH ROW EXECUTE FUNCTION preserve_vehicle_product_serial();
CREATE FUNCTION preserve_doorstep_product_line() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state<>'reserved' OR (NEW.id,NEW.amendment_id,NEW.load_id,NEW.product_id,NEW.quantity,NEW.unit_price_kobo,NEW.name,NEW.serialized) IS DISTINCT FROM (OLD.id,OLD.amendment_id,OLD.load_id,OLD.product_id,OLD.quantity,OLD.unit_price_kobo,OLD.name,OLD.serialized) THEN RAISE EXCEPTION 'Supplementary product obligation is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER doorstep_product_line_guard BEFORE UPDATE OR DELETE ON doorstep_product_lines FOR EACH ROW EXECUTE FUNCTION preserve_doorstep_product_line();
CREATE FUNCTION preserve_doorstep_product_execution() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.state<>'reserved' OR (NEW.amendment_id,NEW.order_id,NEW.trip_id,NEW.note_id,NEW.amount_kobo,NEW.expires_at) IS DISTINCT FROM (OLD.amendment_id,OLD.order_id,OLD.trip_id,OLD.note_id,OLD.amount_kobo,OLD.expires_at) OR (OLD.cash_reported_by IS NOT NULL AND (NEW.cash_reported_by,NEW.cash_reported_at) IS DISTINCT FROM (OLD.cash_reported_by,OLD.cash_reported_at)) OR (OLD.cash_verified_by IS NOT NULL AND (NEW.cash_verified_by,NEW.cash_verified_at) IS DISTINCT FROM (OLD.cash_verified_by,OLD.cash_verified_at)) THEN RAISE EXCEPTION 'Supplementary product collection history is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER doorstep_product_execution_guard BEFORE UPDATE OR DELETE ON doorstep_product_execution FOR EACH ROW EXECUTE FUNCTION preserve_doorstep_product_execution();

INSERT INTO schema_migrations(version) VALUES ('067');
-- Financial exception review never marks unsuccessful work complete or authorises further work.
CREATE TABLE service_work_authority_history(id text PRIMARY KEY,booking_id text NOT NULL REFERENCES service_bookings(id),booking_version integer NOT NULL,quote_id text REFERENCES service_quotes(id),snapshot jsonb NOT NULL,started_by text NOT NULL REFERENCES users(id),started_at timestamptz NOT NULL DEFAULT now(),UNIQUE(booking_id,booking_version));
CREATE TABLE service_exception_settlements(id text PRIMARY KEY,booking_id text NOT NULL REFERENCES service_bookings(id),revision integer NOT NULL CHECK(revision>0),report_id text REFERENCES service_reports(id),source_status text NOT NULL CHECK(source_status IN ('failed','cancelled')),amount_kobo bigint NOT NULL CHECK(amount_kobo>=0),ceiling_kobo bigint NOT NULL CHECK(ceiling_kobo>=amount_kobo),reason text NOT NULL,evidence text NOT NULL,proposed_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(booking_id,revision));
CREATE TABLE service_settlement_consents(id text PRIMARY KEY,settlement_id text NOT NULL UNIQUE REFERENCES service_exception_settlements(id),customer_id text NOT NULL REFERENCES users(id),accepted boolean NOT NULL,notes text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['service_work_authority_history','service_exception_settlements','service_settlement_consents'] LOOP
 EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation()',t);
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN EXECUTE format('GRANT SELECT,INSERT ON %I TO easygas_server',t);EXECUTE format('CREATE POLICY server_only ON %I TO easygas_server USING(true) WITH CHECK(true)',t);END IF;
 END LOOP;END $$;

INSERT INTO schema_migrations(version) VALUES ('068');
