ALTER TABLE credit_requests ADD CONSTRAINT credit_requests_kind_check CHECK(kind IN ('cash_funding','refund','bank_transfer'));
ALTER TABLE credit_requests ADD COLUMN funding_details jsonb;

-- Optional verified identity via the existing independent shared approval workflow.
-- No sample registration/tax values; no changes to historical issued snapshots.
INSERT INTO setting_definitions(key,label,category,description,owner_role,risk,value_type,propose_roles,approve_roles,view_roles,required_roles,additional_verification)
VALUES('document.identity','Verified financial document identity','Business Details','Configure only verified business legal/contact details; record verification evidence. Independent approval required. New documents only; optional fields may remain empty.','owner',3,'document_identity','["owner"]','["owner","finance"]','["owner","finance"]','[]',true);
INSERT INTO settings(key,scope,value) SELECT 'document.identity',id,'null'::jsonb FROM branches;

INSERT INTO schema_migrations(version) VALUES ('072');
INSERT INTO schema_migrations(version) VALUES ('071');
INSERT INTO schema_migrations(version) VALUES ('070');
-- Direct card checkout reuses the sandbox payment orchestrator and verified ledger.
-- Existing invoice/service/wallet targets and financial records are unchanged.
ALTER TABLE payment_intents ADD COLUMN order_id text REFERENCES orders(id);
ALTER TABLE payment_intents DROP CONSTRAINT payment_intents_purpose_check;
ALTER TABLE payment_intents DROP CONSTRAINT payment_intents_check;
ALTER TABLE payment_intents ADD CONSTRAINT payment_intents_purpose_check CHECK(purpose IN ('invoice','service','wallet','order'));
ALTER TABLE payment_intents ADD CONSTRAINT payment_intents_check CHECK(
 (purpose='invoice' AND invoice_id IS NOT NULL AND booking_id IS NULL AND order_id IS NULL) OR
 (purpose='service' AND booking_id IS NOT NULL AND invoice_id IS NULL AND order_id IS NULL) OR
