 (purpose='order' AND order_id IS NOT NULL AND invoice_id IS NULL AND booking_id IS NULL));
CREATE INDEX payment_intents_order ON payment_intents(order_id) WHERE order_id IS NOT NULL;

INSERT INTO schema_migrations(version) VALUES ('073');
-- Supplementary requests share the original order, customer and single fulfilment.
CREATE TABLE order_additions (
 id text PRIMARY KEY, order_id text NOT NULL UNIQUE REFERENCES orders(id),
 actor_id text NOT NULL REFERENCES users(id), request_key text NOT NULL,
 request_hash text NOT NULL, reason text NOT NULL CHECK(length(reason)>=10),
 snapshot jsonb NOT NULL, amount_kobo bigint NOT NULL CHECK(amount_kobo>0),
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_id,request_key)
);
CREATE FUNCTION preserve_order_addition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Order addition records are immutable'; END $$;
CREATE TRIGGER order_addition_immutable BEFORE UPDATE OR DELETE ON order_additions FOR EACH ROW EXECUTE FUNCTION preserve_order_addition();
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN GRANT SELECT,INSERT ON order_additions TO easygas_server; END IF; END $$;
ALTER TABLE order_additions ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 CREATE POLICY trusted_server ON order_additions TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;

INSERT INTO schema_migrations(version) VALUES ('074');
-- Per-user operation overrides; canonical roles, identities and historic approvals remain unchanged.
CREATE TABLE staff_privilege_versions(user_id text PRIMARY KEY REFERENCES users(id),version integer NOT NULL DEFAULT 0 CHECK(version>=0));
CREATE TABLE staff_privilege_overrides(user_id text NOT NULL REFERENCES users(id),privilege text NOT NULL,effect text NOT NULL CHECK(effect IN ('grant','deny')),changed_by text NOT NULL REFERENCES users(id),role_at_change text NOT NULL,branch_at_change text,invalidated_at timestamptz,changed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,privilege));
CREATE INDEX staff_privilege_overrides_actor ON staff_privilege_overrides(changed_by);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT,UPDATE ON staff_privilege_versions TO easygas_server;
 GRANT SELECT,INSERT,UPDATE,DELETE ON staff_privilege_overrides TO easygas_server;
END IF; END $$;
ALTER TABLE staff_privilege_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE staff_privilege_overrides ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 CREATE POLICY trusted_server ON staff_privilege_versions TO easygas_server USING(true) WITH CHECK(true);
 CREATE POLICY trusted_server ON staff_privilege_overrides TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;

-- Grants must never silently reactivate after a role or branch move and later reversal.
CREATE FUNCTION invalidate_staff_privilege_grants() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.role IS DISTINCT FROM NEW.role OR OLD.branch_id IS DISTINCT FROM NEW.branch_id THEN
  UPDATE staff_privilege_overrides SET invalidated_at=now() WHERE user_id=NEW.id AND effect='grant' AND invalidated_at IS NULL;
  INSERT INTO staff_privilege_versions(user_id,version) VALUES(NEW.id,1) ON CONFLICT(user_id) DO UPDATE SET version=staff_privilege_versions.version+1;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER staff_privilege_identity_change AFTER UPDATE OF role,branch_id ON users FOR EACH ROW EXECUTE FUNCTION invalidate_staff_privilege_grants();

INSERT INTO schema_migrations(version) VALUES ('075');
-- Additive support continuation. Legacy requests retain no SLA until explicitly enrolled.
ALTER TABLE support_requests ADD COLUMN version integer NOT NULL DEFAULT 1;
ALTER TABLE support_requests ADD COLUMN sla_policy jsonb;
ALTER TABLE support_requests ADD COLUMN response_due_at timestamptz;
ALTER TABLE support_requests ADD COLUMN resolution_due_at timestamptz;
ALTER TABLE support_requests ADD COLUMN first_response_at timestamptz;
ALTER TABLE support_requests ADD COLUMN resolved_at timestamptz;
CREATE TABLE support_sla_policies(branch_id text PRIMARY KEY REFERENCES branches(id),value jsonb NOT NULL,updated_by text NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_attachments(id text PRIMARY KEY,request_id text NOT NULL REFERENCES support_requests(id),owner_id text NOT NULL REFERENCES users(id),internal boolean NOT NULL DEFAULT false,alt text NOT NULL,mime text NOT NULL CHECK(mime='image/webp'),data bytea NOT NULL CHECK(octet_length(data)<=4000000),sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,owner_id,internal,sha256));
CREATE TABLE support_reply_operations(request_id text NOT NULL REFERENCES support_requests(id),author_id text NOT NULL REFERENCES users(id),operation_id text NOT NULL,fingerprint text NOT NULL,message_id text NOT NULL REFERENCES support_messages(id),PRIMARY KEY(request_id,author_id,operation_id));
CREATE TABLE support_sla_notices(request_id text NOT NULL REFERENCES support_requests(id),kind text NOT NULL,due_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(request_id,kind,due_at));
CREATE INDEX support_customer_page ON support_requests(customer_id,updated_at DESC,id DESC);
CREATE INDEX support_message_page ON support_messages(request_id,created_at,id);
CREATE INDEX support_attachment_ticket ON support_attachments(request_id,created_at,id);
CREATE TRIGGER support_attachments_immutable BEFORE UPDATE OR DELETE ON support_attachments FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TRIGGER support_reply_operations_immutable BEFORE UPDATE OR DELETE ON support_reply_operations FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
ALTER TABLE support_sla_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE support_attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE support_reply_operations ENABLE ROW LEVEL SECURITY;
ALTER TABLE support_sla_notices ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='easygas_server') THEN
 GRANT SELECT,INSERT,UPDATE ON support_sla_policies TO easygas_server;
 GRANT SELECT,INSERT ON support_attachments,support_reply_operations,support_sla_notices TO easygas_server;
 CREATE POLICY trusted_server ON support_sla_policies TO easygas_server USING(true) WITH CHECK(true);
 CREATE POLICY trusted_server ON support_attachments TO easygas_server USING(true) WITH CHECK(true);
 CREATE POLICY trusted_server ON support_reply_operations TO easygas_server USING(true) WITH CHECK(true);
 CREATE POLICY trusted_server ON support_sla_notices TO easygas_server USING(true) WITH CHECK(true);
END IF; END $$;

